  const totals = await getProjectTotals()

  return (
    <main>
      <h1>Workspace</h1>
      <Suspense fallback={<p>Loading...</p>}>
        <MemberDetails />
      </Suspense>
      <p>{totals.active} active projects</p>
    </main>
  )
}

